// 75ns            1               0               0               
// 80ns            1               0               0               
// 85ns            1               1               1               
// 90ns            1               1               1

module top_module (
	input a, 
	input b, 
	output q
);

Erroneous Implementation:

always @(posedge clk) begin 
	q <= a & b; 
end 

endmodule

Feedback:
circuit1.sv:145: error: q is not a valid l-value in tb.top_module1.
circuit1.sv:141:      : q is declared here as wire.
